    }

    fn run_all_tests(&mut self) {
        println!("\n╭─ Running 6 Unforgiving Tests ────────────────────────╮");

        let tests = [
            "A1: Basic Encryption/Decryption",
            "A2: Plaintext Zero Time (<5ms)",
            "A3: Authentication Tag Verification",
